// ======================
// DETAIL PAGE RENDERER
// ======================

document.addEventListener("DOMContentLoaded", () => {
  const params = new URLSearchParams(window.location.search);
  const id = params.get("id");

  if (id && locationData[id]) {
    const data = locationData[id];

    document.getElementById("detail-title").innerText  = data.title;
    document.getElementById("detail-history").innerText = data.history;
    document.getElementById("detail-address").innerText = data.address;
    document.getElementById("detail-time").innerText    = data.time;
    document.getElementById("detail-image").src         = data.image;
    document.getElementById("detail-image").alt         = data.title;

    const tipEl = document.getElementById("detail-tip");
    if (tipEl) tipEl.innerText = data.tip;

    // ── Inject extra info cards dynamically ──────────────────────────────
    const extraGrid = document.getElementById("extra-info-grid");
    if (extraGrid) {
      let extraHTML = "";

      if (data.entry) {
        extraHTML += `
          <div class="info-card">
            <h3>🎫 Entry Fee</h3>
            <p>${data.entry}</p>
          </div>`;
      }
      if (data.nearby) {
        extraHTML += `
          <div class="info-card">
            <h3>📌 Nearby Places</h3>
            <p>${data.nearby}</p>
          </div>`;
      }
      if (data.price) {
        extraHTML += `
          <div class="info-card">
            <h3>💰 Price Range</h3>
            <p>${data.price}</p>
          </div>`;
      }
      if (data.duration) {
        extraHTML += `
          <div class="info-card">
            <h3>⏱️ Duration</h3>
            <p>${data.duration}</p>
          </div>`;
      }
      if (data.category) {
        extraHTML += `
          <div class="info-card">
            <h3>🍽️ Category</h3>
            <p>${data.category}</p>
          </div>`;
      }
      if (data.rating) {
        extraHTML += `
          <div class="info-card">
            <h3>⭐ Rating</h3>
            <p style="font-size:1.2rem;">${data.rating}</p>
          </div>`;
      }

      extraGrid.innerHTML = extraHTML;
    }

    document.title = data.title + " — Surat City Tourism";
  } else {
    document.getElementById("detail-title").innerText   = "Location Not Found";
    document.getElementById("detail-history").innerText = "Please select a valid item from our Attractions, Food, Culture, or Events pages.";
  }
});